249: idevice_error_t idevice_events_subscribe(idevice_subscription_context_t *context, idevice_event_cb_t callback, void *user_data)
250: {
251: 	if (!context || !callback) {
252: 		return IDEVICE_E_INVALID_ARG;
253: 	}
254: 	*context = malloc(sizeof(struct idevice_subscription_context));
255: 	if (!*context) {
256: 		debug_info("ERROR: %s: Failed to allocate subscription context\n", __func__);
257: 		return IDEVICE_E_UNKNOWN_ERROR;
258: 	}
259: 	(*context)->callback = callback;
260: 	(*context)->user_data = user_data;
261: 	int res = usbmuxd_events_subscribe(&(*context)->ctx, usbmux_event_cb, *context);
262: 	if (res != 0) {
263: 		free(*context);
264: 		*context = NULL;
265: 		debug_info("ERROR: usbmuxd_subscribe() returned %d!", res);
266: 		return IDEVICE_E_UNKNOWN_ERROR;
267: 	}
268: 	return IDEVICE_E_SUCCESS;
269: }
