271: idevice_error_t idevice_events_unsubscribe(idevice_subscription_context_t context)
272: {
273: 	if (!context) {
274: 		return IDEVICE_E_INVALID_ARG;
275: 	}
276: 	int res = usbmuxd_events_unsubscribe(context->ctx);
277: 	if (res != 0) {
278: 		debug_info("ERROR: usbmuxd_unsubscribe() returned %d!", res);
279: 		return IDEVICE_E_UNKNOWN_ERROR;
280: 	}
281: 	if (context == event_ctx) {
282: 		event_ctx = NULL;
283: 	}
284: 	free(context);
285: 	return IDEVICE_E_SUCCESS;
286: }
