502: idevice_error_t idevice_free(idevice_t device)
503: {
504: 	if (!device)
505: 		return IDEVICE_E_INVALID_ARG;
506: 	idevice_error_t ret = IDEVICE_E_UNKNOWN_ERROR;
507: 
508: 	ret = IDEVICE_E_SUCCESS;
509: 
510: 	free(device->udid);
511: 
512: 	if (device->conn_data) {
513: 		free(device->conn_data);
514: 	}
515: 	free(device);
516: 	return ret;
