600: idevice_error_t idevice_disconnect(idevice_connection_t connection)
601: {
602: 	if (!connection) {
603: 		return IDEVICE_E_INVALID_ARG;
604: 	}
605: 	/* shut down ssl if enabled */
606: 	if (connection->ssl_data) {
607: 		idevice_connection_disable_ssl(connection);
608: 	}
609: 	idevice_error_t result = IDEVICE_E_UNKNOWN_ERROR;
610: 	if (connection->type == CONNECTION_USBMUXD) {
611: 		usbmuxd_disconnect((int)(uintptr_t)connection->data);
612: 		connection->data = NULL;
613: 		result = IDEVICE_E_SUCCESS;
614: 	} else if (connection->type == CONNECTION_NETWORK) {
615: 		socket_close((int)(uintptr_t)connection->data);
616: 		connection->data = NULL;
617: 		result = IDEVICE_E_SUCCESS;
618: 	} else {
619: 		debug_info("Unknown connection type %d", connection->type);
620: 	}
621: 
622: 	free(connection);
623: 	connection = NULL;
624: 
625: 	return result;
626: }
