628: /**
629:  * Internally used function to send raw data over the given connection.
630:  */
631: static idevice_error_t internal_connection_send(idevice_connection_t connection, const char *data, uint32_t len, uint32_t *sent_bytes)
632: {
633: 	if (!connection || !data) {
634: 		return IDEVICE_E_INVALID_ARG;
635: 	}
636: 
637: 	if (connection->type == CONNECTION_USBMUXD) {
638: 		int res;
639: 		do {
640: 			res = usbmuxd_send((int)(uintptr_t)connection->data, data, len, sent_bytes);
641: 		} while (res == -EAGAIN);
642: 		if (res < 0) {
643: 			debug_info("ERROR: usbmuxd_send returned %d (%s)", res, strerror(-res));
644: 			return IDEVICE_E_UNKNOWN_ERROR;
645: 		}
646: 		return IDEVICE_E_SUCCESS;
647: 	}
648: 	if (connection->type == CONNECTION_NETWORK) {
649: 		int s = socket_send((int)(uintptr_t)connection->data, (void*)data, len);
650: 		if (s < 0) {
651: 			*sent_bytes = 0;
652: 			return IDEVICE_E_UNKNOWN_ERROR;
653: 		}
654: 		*sent_bytes = s;
655: 		return IDEVICE_E_SUCCESS;
656: 	}
657: 
658: 	debug_info("Unknown connection type %d", connection->type);
659: 	return IDEVICE_E_UNKNOWN_ERROR;
660: 
661: }
