745: /**
746:  * Internally used function for receiving raw data over the given connection
747:  * using a timeout.
748:  */
749: static idevice_error_t internal_connection_receive_timeout(idevice_connection_t connection, char *data, uint32_t len, uint32_t *recv_bytes, unsigned int timeout)
750: {
751: 	if (!connection) {
752: 		return IDEVICE_E_INVALID_ARG;
753: 	}
754: 
755: 	if (connection->type == CONNECTION_USBMUXD) {
756: 		int conn_error = usbmuxd_recv_timeout((int)(uintptr_t)connection->data, data, len, recv_bytes, timeout);
757: 		idevice_error_t error = socket_recv_to_idevice_error(conn_error, len, *recv_bytes);
758: 		if (error == IDEVICE_E_UNKNOWN_ERROR) {
759: 			debug_info("ERROR: usbmuxd_recv_timeout returned %d (%s)", conn_error, strerror(-conn_error));
760: 		}
761: 		return error;
762: 	}
763: 	if (connection->type == CONNECTION_NETWORK) {
764: 		int res = socket_receive_timeout((int)(uintptr_t)connection->data, data, len, 0, timeout);
765: 		idevice_error_t error = socket_recv_to_idevice_error(res, 0, 0);
766: 		if (error == IDEVICE_E_SUCCESS) {
767: 			*recv_bytes = (uint32_t)res;
768: 		} else if (error == IDEVICE_E_UNKNOWN_ERROR) {
769: 			debug_info("ERROR: socket_receive_timeout returned %d (%s)", res, strerror(-res));
770: 		}
771: 		return error;
772: 	}
773: 
774: 	debug_info("Unknown connection type %d", connection->type);
775: 	return IDEVICE_E_UNKNOWN_ERROR;
776: }
