969: /**
970:  * Internally used SSL callback function for receiving encrypted data.
971:  */
972: static ssl_cb_ret_type_t internal_ssl_read(idevice_connection_t connection, char *buffer, size_t length)
973: {
974: 	uint32_t bytes = 0;
975: 	uint32_t pos = 0;
976: 	idevice_error_t res;
977: 	unsigned int timeout = connection->ssl_recv_timeout;
978: 
979: 	debug_info("pre-read length = %zi bytes", length);
980: 
981: 	/* repeat until we have the full data or an error occurs */
982: 	do {
983: 		bytes = 0;
984: 		if (timeout == (unsigned int)-1) {
985: 			res = internal_connection_receive(connection, buffer + pos, (uint32_t)length - pos, &bytes);
986: 		} else {
987: 			res = internal_connection_receive_timeout(connection, buffer + pos, (uint32_t)length - pos, &bytes, (unsigned int)timeout);
988: 		}
989: 		if (res != IDEVICE_E_SUCCESS) {
990: 			if (res != IDEVICE_E_TIMEOUT) {
991: 				debug_info("ERROR: %s returned %d", (timeout == (unsigned int)-1) ? "internal_connection_receive" : "internal_connection_receive_timeout", res);
992: 			}
993: 			connection->status = res;
994: 			return -1;
995: 		}
996: 		debug_info("read %i bytes", bytes);
997: 
998: 		/* increase read count */
999: 		pos += bytes;
1000: 		if (pos < (uint32_t)length) {
1001: 			debug_info("re-read trying to read missing %i bytes", (uint32_t)length - pos);
1002: 		}
1003: 	} while (pos < (uint32_t)length);
1004: 
1005: 	debug_info("post-read received %i bytes", pos);
1006: 
1007: 	return pos;
1008: }
