1010: /**
1011:  * Internally used SSL callback function for sending encrypted data.
1012:  */
1013: static ssl_cb_ret_type_t internal_ssl_write(idevice_connection_t connection, const char *buffer, size_t length)
1014: {
1015: 	uint32_t bytes = 0;
1016: 	idevice_error_t res;
1017: 	debug_info("pre-send length = %zi bytes", length);
1018: 	if ((res = internal_connection_send(connection, buffer, length, &bytes)) != IDEVICE_E_SUCCESS) {
1019: 		debug_info("ERROR: internal_connection_send returned %d", res);
1020: 		connection->status = res;
1021: 		return -1;
1022: 	}
1023: 	debug_info("post-send sent %i bytes", bytes);
1024: 	return bytes;
1025: }
