1027: /**
1028:  * Internally used function for cleaning up SSL stuff.
1029:  */
1030: static void internal_ssl_cleanup(ssl_data_t ssl_data)
1031: {
1032: 	if (!ssl_data)
1033: 		return;
1034: 
1035: #if defined(HAVE_OPENSSL)
1036: 	if (ssl_data->session) {
1037: 		SSL_free(ssl_data->session);
1038: 	}
1039: 	if (ssl_data->ctx) {
1040: 		SSL_CTX_free(ssl_data->ctx);
1041: 	}
1042: #elif defined(HAVE_GNUTLS)
1043: 	if (ssl_data->session) {
1044: 		gnutls_deinit(ssl_data->session);
1045: 	}
1046: 	if (ssl_data->certificate) {
1047: 		gnutls_certificate_free_credentials(ssl_data->certificate);
1048: 	}
1049: 	if (ssl_data->root_cert) {
1050: 		gnutls_x509_crt_deinit(ssl_data->root_cert);
1051: 	}
1052: 	if (ssl_data->host_cert) {
1053: 		gnutls_x509_crt_deinit(ssl_data->host_cert);
1054: 	}
1055: 	if (ssl_data->root_privkey) {
1056: 		gnutls_x509_privkey_deinit(ssl_data->root_privkey);
1057: 	}
1058: 	if (ssl_data->host_privkey) {
1059: 		gnutls_x509_privkey_deinit(ssl_data->host_privkey);
